DROP TABLE IF EXISTS `sys_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父菜单ID,0为根',
  `menu_name` varchar(100) NOT NULL COMMENT '菜单名称',
  `menu_type` char(1) NOT NULL COMMENT 'M目录 C菜单 F按钮',
  `path` varchar(200) DEFAULT NULL COMMENT '路由地址',
  `component` varchar(255) DEFAULT NULL COMMENT '组件路径',
  `perms` varchar(255) DEFAULT NULL COMMENT '权限码，可逗号多码',
  `icon` varchar(100) DEFAULT NULL COMMENT '图标',
  `feature_code` varchar(64) DEFAULT NULL COMMENT '所属功能点,用于套餐开关过滤',
  `terminal` varchar(20) NOT NULL DEFAULT 'PC' COMMENT '适用端:PC/H5/ALL',
  `sort` int NOT NULL DEFAULT '0',
  `visible` tinyint NOT NULL DEFAULT '1' COMMENT '1显示 0隐藏',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_feature` (`feature_code`),
  KEY `idx_terminal` (`terminal`)
) ENGINE=InnoDB AUTO_INCREMENT=3941 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户端菜单[全局表-无tenant_id]';
